// Извлекаем тендеры из Serper/Tavily — без Firecrawl
// Сниппеты уже содержат достаточно данных
const cfg = $('Config').first().json;
const urls = new Set();
const items = [];

const inputItems = $input.all() || [];
for (const item of inputItems) {
  if (!item || !item.json) continue;
  const j = item.json;
  const organic = j.organic || [];
  const results = j.results || [];

  // Serper organic
  for (const o of organic) {
    const link = o.link;
    if (!link || urls.has(link)) continue;
    // Пропускаем только явно нерелевантные URL
    if (link.includes('youtube.com') || link.includes('instagram.com') || link.includes('facebook.com')) continue;
    urls.add(link);
    items.push({
      json: {
        url: link,
        title: o.title || '',
        snippet: o.snippet || '',
        job_id: cfg.job_id,
        source: 'serper'
      }
    });
  }

  // Tavily results
  for (const r of results) {
    const link = r.url;
    if (!link || urls.has(link)) continue;
    if (link.includes('youtube.com') || link.includes('instagram.com')) continue;
    urls.add(link);
    items.push({
      json: {
        url: link,
        title: r.title || '',
        snippet: r.content || r.snippet || '',
        job_id: cfg.job_id,
        source: 'tavily'
      }
    });
  }
}

return items.slice(0, 10).length > 0 ? items.slice(0, 10) : [{ json: { skip: true } }];

const item = $input.first();
if (!item || !item.json) return [{ json: { skip: true } }];

// Парсим ответ DeepSeek
const raw = item.json.choices?.[0]?.message?.content || '{}';
let p = {};
try {
  const cleanRaw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  p = JSON.parse(cleanRaw);
} catch(e) {
  p = {};
}

// Текущий кандидат цикла — текущий item ноды Loop Tenders (paired item)
let ctx = {};
try {
  ctx = $('Loop Tenders').item.json || {};
} catch(e) {
  ctx = {};
}

const sourceUrl = ctx.url || '';
const sourceTitle = ctx.title || '';
const sourceSnippet = ctx.snippet || '';

// Извлекаем hostname из URL
let hostname = 'unknown';
try {
  const hm = sourceUrl.match(/^(?:https?:\/\/)?(?:www\.)?([^\/]+)/i);
  if (hm && hm[1]) hostname = hm[1];
} catch(e) {}

// Бюджет — из DeepSeek или из snippet
let budget = Number(p.budget_estimated) || 0;
if (!budget) {
  const budgetM = sourceSnippet.match(/([\d\s.,]+)\s*(?:руб|₽|тыс|млн)/i);
  if (budgetM && budgetM[1]) {
    const num = parseInt(budgetM[1].replace(/\D/g, ''), 10) || 0;
    if (/млн/i.test(budgetM[0])) budget = num * 1000000;
    else if (/тыс/i.test(budgetM[0])) budget = num * 1000;
    else budget = num;
  }
}

const reqs = Array.isArray(p.required_prerequisites) ? p.required_prerequisites.join('; ') : (p.required_prerequisites || '');
const summary = p.summary_ru || sourceSnippet || '';

return [{
  json: {
    tender_id: 'tnd_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10),
    job_id: ctx.job_id || '',
    platform: hostname,
    url: sourceUrl,
    title: sourceTitle || p.matched_service || '',
    budget: budget,
    deadline: p.deadline_date || null,
    tender_number: p.tender_number || null,
    raw_content: summary.slice(0, 3000),
    relevance_score: Number(p.relevance_score) || 0,
    matched_service: p.matched_service || '',
    win_probability: Number(p.win_probability) || 0,
    required_prerequisites: reqs,
    summary: summary,
    total_score: Number(p.relevance_score) || 0,
    scraped_at: new Date().toISOString(),
    entity_type: 'tender'
  }
}];

// Собираем единый объект handoff для WF5 после завершения цикла.
const cfg = $('Config').first().json || {};
const jobId = cfg.job_id || 'unknown';
const requestedCount = cfg.requested_count != null ? cfg.requested_count : null;

// DONE вход накапливает обработанные кандидаты (relevance_score у каждого).
const processed = $input.all() || [];
const accepted = processed.filter(i => {
  if (!i || !i.json) return false;
  return Number(i.json.relevance_score) >= 20;
}).length;

return [{
  json: {
    job_id: jobId,
    entity_type: 'tender',
    accepted_count: accepted,
    requested_count: requestedCount
  }
}];
